import traceback
from collections import defaultdict
from functools import wraps

import pytest


def positive_int(value):
    value = int(value)
    if value < 0:
        raise ValueError(f"Argument {value} must be non-negative")
    return value


def pytest_addoption(parser):
    """Add options to split the test suite into deterministic shards.

    Adapted from https://github.com/AdamGleave/pytest-shard so a single
    pandas-tests job can be parallelized across multiple CI runners. With the
    defaults (``--num-shards 1``) the full suite runs, so existing
    (non-sharded) invocations are unaffected.
    """
    group = parser.getgroup("shard")
    group.addoption(
        "--shard-id",
        dest="shard_id",
        type=positive_int,
        default=0,
        help="Zero-based index of this shard.",
    )
    group.addoption(
        "--num-shards",
        dest="num_shards",
        type=positive_int,
        default=1,
        help="Total number of shards.",
    )


def _sha256_hash(value: str) -> int:
    return int.from_bytes(hashlib.sha256(value.encode()).digest(), "little")


def partition_items_by_shard(items, shard_id, num_shards):
    """Split ``items`` into those assigned to ``shard_id`` and the rest.

    Assignment is by a stable hash of each item's node id, so every pytest
    worker (and every shard) partitions the suite identically and the shards
    are disjoint and collectively exhaustive.
    """
    selected, deselected = [], []
    for item in items:
        target = (
            selected
            if (_sha256_hash(item.nodeid) % num_shards == shard_id)
            else deselected
        )
        target.append(item)
    return selected, deselected


def pytest_report_collectionfinish(config, items):
    if config.getoption("num_shards") > 1:
        return (
            f"Running {len(items)} items in shard "
            f"{config.getoption('shard_id')}/{config.getoption('num_shards')}"
        )


def replace_kwargs(new_kwargs):
    def wrapper(func):
        @wraps(func)
        def wrapped(*args, **kwargs):
            kwargs.update(new_kwargs)
            return func(*args, **kwargs)

        return wrapped

    return wrapper


@pytest.fixture(scope="session", autouse=True)
def patch_testing_functions():
    pytest.raises = replace_kwargs({"match": None})(pytest.raises)


# Node ids (matched by substring) whose only discrepancy from pandas is a
# small (~1e-6) GPU-vs-CPU floating-point difference in transcendental numpy
# ufuncs. Matching tests are tagged with the ``tolerant_index_compare`` marker
# during collection (see ``pytest_collection_modifyitems``), and
# ``relax_exact_index_compare`` relaxes ``tm.assert_index_equal`` from its
# default exact check to a tolerant one (with a tight ``rtol``) for them.
NODEIDS_TOLERANT_INDEX_COMPARE = ("test_numpy_ufuncs_basic",)


@pytest.fixture(autouse=True)
def relax_exact_index_compare(request):
    if request.node.get_closest_marker("tolerant_index_compare") is None:
        yield
        return
    import pandas._testing as tm

    original = tm.assert_index_equal
    tm.assert_index_equal = replace_kwargs(
        {"check_exact": False, "rtol": 1e-6}
    )(original)
    try:
        yield
    finally:
        tm.assert_index_equal = original


# Dictionary to store function call counts
function_call_counts = defaultdict(lambda: defaultdict(int))  # type: ignore[var-annotated]

# The specific functions to track
FUNCTION_NAME = {"_slow_function_call", "_fast_function_call"}


def find_pytest_file(frame) -> str | None:
    for frame in traceback.extract_stack():
        file = frame.filename
        if "pandas-testing/pandas-tests/tests" in file and file.rsplit("/", 1)[
            -1
        ].startswith("test_"):
            return str(file).rsplit("pandas-tests/", 1)[-1]
    return None


def trace_calls(frame, event, arg):
    if (
        event == "call"
        and (func_name := frame.f_code.co_name) in FUNCTION_NAME
        and (filename := find_pytest_file(frame)) is not None
    ):
        function_call_counts[filename][func_name] += 1


def pytest_sessionstart(session):
    # Set the profile function to trace calls
    sys.setprofile(trace_calls)


def pytest_sessionfinish(session, exitstatus):
    # Remove the profile function
    sys.setprofile(None)


@pytest.hookimpl(trylast=True)
def pytest_unconfigure(config):
    if hasattr(config, "workerinput"):
        # Running in xdist worker, write the counts before exiting
        worker_id = config.workerinput["workerid"]
        output_file = f"function_call_counts_worker_{worker_id}.json"
        with open(output_file, "w") as f:
            json.dump(function_call_counts, f, indent=4)
        print(f"Function call counts have been written to {output_file}")  # noqa: T201


